def image_to_base64_jpeg(uploaded_file, max_width=MAX_IMAGE_WIDTH, quality=75):
    """Redimensionne et encode une capture d'ecran en base64 (JPEG).

    Retourne (data_uri, largeur, hauteur) — la largeur/hauteur servent a
    fixer les attributs width/height dans le HTML final (evite les sauts
    de mise en page pendant le chargement).
    """
    img = Image.open(uploaded_file)
    if img.mode in ("RGBA", "P"):
        img = img.convert("RGB")
    if img.width > max_width:
        ratio = max_width / img.width
        img = img.resize((max_width, int(img.height * ratio)))
    buffer = io.BytesIO()
    img.save(buffer, format="JPEG", quality=quality, optimize=True)
    encoded = base64.b64encode(buffer.getvalue()).decode("utf-8")
    return f"data:image/jpeg;base64,{encoded}", img.width, img.height


def deplacer_article(index, direction):
    articles = st.session_state.articles
    nouvel_index = index + direction
    if 0 <= nouvel_index < len(articles):
        articles[index], articles[nouvel_index] = articles[nouvel_index], articles[index]


def supprimer_article(article_id):
    st.session_state.articles = [a for a in st.session_state.articles if a["id"] != article_id]


